from pathlib import Path
import base64
import zlib

FILES = {
    "AdvancedCore/src/main/java/com/bencodez/advancedcore/api/javascript/JavascriptPlaceholderBinder.java": "",
    "AdvancedCore/src/test/java/com/bencodez/advancedcore/api/javascript/JavascriptPlaceholderBinderTest.java": ""
}

for filename, payload in FILES.items():
    path = Path(filename)
    if not path.exists():
        raise SystemExit(f"Expected file is missing: {filename}")
    path.write_bytes(zlib.decompress(base64.b64decode(payload)))
